#!/bin/sh
set -eu

compose="docker compose"

$compose exec -T -u www-data moodle php admin/cli/cfg.php --name=theme --set=boost
$compose exec -T -u www-data moodle php admin/cli/cfg.php --component=theme_boost --name=brandcolor --set='#2563eb'
$compose exec -T -u www-data moodle php admin/cli/cfg.php --component=theme_boost --name=scsspre \
  --set='$primary: #2563eb; $secondary: #64748b; $body-bg: #f7f8fc; $border-radius: .625rem; $border-radius-lg: .875rem; $font-family-sans-serif: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;'
$compose exec -T -u www-data moodle php admin/cli/cfg.php --component=theme_boost --name=scss \
  --set='body { color: #1e293b; -webkit-font-smoothing: antialiased; } .navbar.fixed-top { min-height: 64px; background: rgba(255,255,255,.98) !important; border: 0; border-bottom: 1px solid #e8ecf2; box-shadow: 0 1px 3px rgba(15,23,42,.04); } .navbar-brand { color: #0f172a !important; font-size: 1.2rem; font-weight: 750; letter-spacing: -.02em; } .navbar.fixed-top .nav-link { color: #475569 !important; border: 0 !important; border-radius: .55rem; margin: 0 .12rem; padding: .55rem .78rem !important; font-weight: 540; transition: color .15s ease, background-color .15s ease; } .navbar.fixed-top .nav-link:hover { color: #0f172a !important; background: #f1f5f9; } .navbar.fixed-top .nav-link.active, .navbar.fixed-top .nav-link[aria-current="page"] { color: #1d4ed8 !important; background: #eff6ff; box-shadow: none; } .navbar.fixed-top .nav-link.active::after { display: none !important; } #page { background: #f7f8fc; } #page.drawers .main-inner { max-width: 1440px; background: transparent; } #page-header { background: transparent; border: 0; border-radius: 0; box-shadow: none; margin: .5rem 0 1.75rem; padding: 0; } #page-header h1, #page-header h2 { color: #0f172a; font-weight: 720; letter-spacing: -.035em; } .breadcrumb { background: transparent; color: #64748b; font-size: .875rem; padding-left: 0; } .card, .block { background: #fff; border: 1px solid #e7ebf0; border-radius: .8rem; box-shadow: 0 1px 2px rgba(15,23,42,.035); } .card-header { background: #fff; border-bottom: 1px solid #edf0f4; color: #0f172a; font-weight: 650; padding: 1rem 1.2rem; } .coursebox, .activity-item { background: #fff; border: 1px solid #e7ebf0 !important; border-radius: .7rem !important; margin-bottom: .7rem; padding: 1rem 1.1rem !important; transition: border-color .15s ease, box-shadow .15s ease; } .coursebox:hover, .activity-item:hover { border-color: #cbd5e1 !important; box-shadow: 0 4px 12px rgba(15,23,42,.055); transform: none; } .nav-tabs { border-bottom: 1px solid #e2e8f0; gap: .2rem; } .nav-tabs .nav-link { color: #64748b; background: transparent !important; border: 0 !important; border-bottom: 2px solid transparent !important; border-radius: 0; padding: .8rem 1rem; } .nav-tabs .nav-link:hover { color: #0f172a; border-bottom-color: #cbd5e1 !important; } .nav-tabs .nav-link.active { color: #1d4ed8; border-bottom-color: #2563eb !important; font-weight: 650; } .btn { border-radius: .55rem; font-weight: 620; box-shadow: none !important; } .btn-primary { background: #2563eb; border-color: #2563eb; } .btn-primary:hover, .btn-primary:focus { background: #1d4ed8; border-color: #1d4ed8; } .drawer { background: #fff; border-color: #e7ebf0; box-shadow: none; } a { color: #2563eb; text-decoration-thickness: 1px; text-underline-offset: 2px; } a:hover { color: #1d4ed8; } .login-container { background: #fff; border: 1px solid #e7ebf0; border-radius: 1rem; box-shadow: 0 18px 45px rgba(15,23,42,.09); padding: 2rem; } .login-container::before { content: "FotoAula"; display: block; color: #0f172a; font-size: 1.45rem; font-weight: 750; letter-spacing: -.03em; margin-bottom: 1.4rem; text-align: center; } #page-footer { background: #fff; border-top: 1px solid #e7ebf0; color: #64748b; } #page-footer a { color: #475569; }'
$compose exec -T -u www-data moodle php admin/cli/purge_caches.php

echo "Tema de Aula de Fotografia aplicado correctamente."
